    private void initMessages() {
        MESSAGE_NO_EVENT = MlM("Please select an event.");
        MESSAGE_NO_EVENTS = MlM("No events found for this billing period.");
        MESSAGE_EXPORT_TITLE = MlM("Export ODS");
        MESSAGE_EXPORT_FINISHED = MlM("Export finished.\nSpreadsheet: %s");
        MESSAGE_EXPORT_FAILED = MlM("Export failed: %s");
    }

    @Override
    public void close() {
        DBEvent event = getSelectedEvent();
        if (event != null && event.name != null && event.name.getValue() != null) {
            root.getSetup().setLocalConfig(CONFIG_EVENT + mainwin.getAZ().title, event.name.getValue());
        }
        super.close();
    }

    private void loadEvents() {
        new AutoMBox(getTitle()) {
            @Override
            public void do_stuff() throws Exception {
                loadingEvents = true;
                try {
                    DBEvent eventProto = new DBEvent();
                    List<DBEvent> events = getTransaction().fetchTable2(eventProto,
                            "where " + getTransaction().markColumn(eventProto.bp_idx) + " = " + mainwin.getAZ().idx
                            + " order by " + getTransaction().markColumn(eventProto.name));

                    jCBEvent.removeAllItems();
                    for (DBEvent event : events) {
                        jCBEvent.addItem(event);
                    }

                    String saved = root.getSetup().getLocalConfig(CONFIG_EVENT + mainwin.getAZ().title, "");
                    if (!saved.isEmpty()) {
                        for (int i = 0; i < jCBEvent.getItemCount(); i++) {
                            DBEvent event = jCBEvent.getItemAt(i);
                            if (event.name != null && saved.equals(event.name.getValue())) {
                                jCBEvent.setSelectedIndex(i);
                                break;
                            }
                        }
                    }
                } finally {
                    loadingEvents = false;
                }
            }
        };
    }

    private DBEvent getSelectedEvent() {
        Object selected = jCBEvent.getSelectedItem();
        return selected instanceof DBEvent ? (DBEvent) selected : null;
    }

    private void generateReport() {
        new AutoMBox(getTitle()) {
            @Override
            public void do_stuff() throws Exception {
                setWaitCursor();
                try {
                    DBEvent event = getSelectedEvent();
                    if (event == null) {
                        jReport.setText("<html><body>" + (jCBEvent.getItemCount() == 0 ? MESSAGE_NO_EVENTS : MESSAGE_NO_EVENT)
                                + "</body></html>");
                        return;
                    }

                    ReportEventPaymentsRenderer renderer = createRenderer(event);
                    jReport.setText(renderer.render());
                    jReport.setCaretPosition(0);
                } finally {
                    setWaitCursor(false);
                }
            }
        };
    }

    private ReportEventPaymentsRenderer createRenderer(DBEvent event) {
        ReportEventPaymentsRenderer renderer =
                new ReportEventPaymentsRenderer(getTransaction(), mainwin.getAZ(), event);
        renderer.collectData();
        return renderer;
    }

    private void exportToODS() {
        final DBEvent event = getSelectedEvent();
        if (event == null) {
            JOptionPane.showMessageDialog(this, MESSAGE_NO_EVENT, MESSAGE_EXPORT_TITLE,
                    JOptionPane.WARNING_MESSAGE);
            return;
        }

        JFileChooser chooser = new JFileChooser(mainwin.getLastOpenPath());
        chooser.setDialogTitle(MESSAGE_EXPORT_TITLE);
        chooser.setSelectedFile(new File(sanitizeFileName(event.name.getValue()) + ".ods"));
        if (chooser.showSaveDialog(this) != JFileChooser.APPROVE_OPTION) {
            return;
        }

        final File targetFile;
        File selected = chooser.getSelectedFile();
        if (!selected.getName().toLowerCase().endsWith(".ods")) {
            targetFile = new File(selected.getAbsolutePath() + ".ods");
        } else {
            targetFile = selected;
        }
        mainwin.setLastOpenPath(targetFile.getParent());

        new AutoMBox(MESSAGE_EXPORT_TITLE) {
            @Override
            public void do_stuff() throws Exception {
                setWaitCursor();
                try {
                    ReportEventPaymentsRenderer renderer = createRenderer(event);
                    writeOds(targetFile, renderer);
                } catch (Exception ex) {
                    setWaitCursor(false);
                    JOptionPane.showMessageDialog(ReportEventPayments.this,
                            String.format(MESSAGE_EXPORT_FAILED, ex.getMessage()),
                            MESSAGE_EXPORT_TITLE, JOptionPane.ERROR_MESSAGE);
                    return;
                }
                setWaitCursor(false);
                JOptionPane.showMessageDialog(ReportEventPayments.this,
                        String.format(MESSAGE_EXPORT_FINISHED, targetFile.getAbsolutePath()),
                        MESSAGE_EXPORT_TITLE, JOptionPane.INFORMATION_MESSAGE);
            }
        };
    }

    private static void writeOds(File targetFile, ReportEventPaymentsRenderer renderer) throws Exception {
        OdfSpreadsheetDocument spreadsheet = OdfSpreadsheetDocument.newSpreadsheetDocument();
        OdfTable table = spreadsheet.getSpreadsheetTables().get(0);
        table.setTableName("Event Payments");
        // the default sheet of a new document is not printable
        table.getOdfElement().setTablePrintAttribute(true);

        final int columnCount = 8;
        ensureColumns(table, columnCount);

        // odfdom does not allow removing the last remaining row of a sheet,
        // so the existing empty row is reused for the first report line.
        OdfTableRow titleRow = table.getRowCount() > 0 ? table.getRowByIndex(0) : appendCleanRow(table);
        setText(titleRow, 0, "Event Payments - " + renderer.getEventName(), true, null);

        OdfTableRow periodRow = appendCleanRow(table);
        if (renderer.getBillingPeriod() != null && renderer.getBillingPeriod().title != null) {
            setText(periodRow, 0, renderer.getBillingPeriod().title.toString(), true, null);
        }

        appendCleanRow(table); // spacer

        appendKV(table, "Participants", renderer.getParticipantCount());
        appendKV(table, "Fee per person", renderer.getFeePerPerson());
        appendKV(table, "Costs (sum)", renderer.getTotalCosts());
        appendKV(table, "Total paid", renderer.getTotalPaid());
        appendKV(table, "Open", renderer.getTotalOpen());

        appendCleanRow(table); // spacer

        OdfTableRow headerRow = appendCleanRow(table);
        String[] header = {"#", "Name", "Group", "Costs (€)", "Paid (€)", "Paid cash (€)",
            "Total paid (€)", "Open (€)"};
        for (int i = 0; i < header.length; i++) {
            setText(headerRow, i, header[i], true, null);
        }

        int number = 1;
        for (ReportEventPaymentsRenderer.Row row : renderer.getRows()) {
            OdfTableRow dataRow = appendCleanRow(table);
            setText(dataRow, 0, String.valueOf(number), false, null);
            setText(dataRow, 1, row.getDisplayName(), false, null);
            setText(dataRow, 2, row.getGroup(), false, null);
            setMoney(dataRow, 3, row.getCosts(), false, null);
            setMoney(dataRow, 4, row.getPaid(), false, null);
            setMoney(dataRow, 5, row.getPaidCash(), false, null);
            setMoney(dataRow, 6, row.getTotalPaid(), false, null);
            setMoney(dataRow, 7, row.getOpen(), false, null);
            number++;
        }

        OdfTableRow totalRow = appendCleanRow(table);
        setText(totalRow, 0, "", true, null);
        setText(totalRow, 1, "Total", true, null);
        setText(totalRow, 2, "", true, null);
        setMoney(totalRow, 3, renderer.getTotalCosts(), true, null);
        setMoney(totalRow, 4, renderer.getTotalPaidBank(), true, null);
        setMoney(totalRow, 5, renderer.getTotalPaidCash(), true, null);
        setMoney(totalRow, 6, renderer.getTotalPaid(), true, null);
        setMoney(totalRow, 7, renderer.getTotalOpen(), true, null);

        setColumnWidths(table);

        try (FileOutputStream fos = new FileOutputStream(targetFile)) {
            spreadsheet.save(fos);
        }
    }

    private static String sanitizeFileName(String name) {
        if (name == null || name.trim().isEmpty()) {
            return "Event-Payments";
        }
        return name.replaceAll("[^a-zA-Z0-9._ -]", "_").trim();
    }

    // ------------------------------------------------------------------
    // ODS helpers
    // ------------------------------------------------------------------

    /**
     * odfdom's appendRow() copies the cell style names of the previous row, which
     * would spread the header background (and bold) over all following rows.
     * The cloned style names are removed so every new row starts unstyled.
     */
    private static OdfTableRow appendCleanRow(OdfTable table) {
        OdfTableRow row = table.appendRow();
        for (int i = 0; i < table.getColumnCount(); i++) {
            row.getCellByIndex(i).getOdfElement().removeAttribute("table:style-name");
        }
        return row;
    }

    private static void ensureColumns(OdfTable table, int columnCount) {
        if (table.getColumnCount() < columnCount) {
            table.appendColumns(columnCount - table.getColumnCount());
        }
    }

    private static void setText(OdfTableRow row, int column, String value, boolean bold, String background) {
        if ((value == null || value.isEmpty()) && !bold && background == null) {
            return;
        }
        OdfTableCell cell = row.getCellByIndex(column);
        cell.setStringValue(value != null ? value : "");
        if (bold) {
            cell.getOdfElement().setProperty(OdfTextProperties.FontWeight, "bold");
        }
        if (background != null) {
            cell.getOdfElement().setProperty(OdfTableCellProperties.BackgroundColor, background);
        }
    }

    /** Writes a numeric money cell; zero values are written explicitly. */
    private static void setMoney(OdfTableRow row, int column, double value, boolean bold, String background) {
        OdfTableCell cell = row.getCellByIndex(column);
        cell.setDoubleValue(value);
        cell.setFormatString("€ #,##0.00");
        if (value < 0.0) {
            cell.getOdfElement().setProperty(OdfTextProperties.Color, "#c00000");
        }
        if (bold) {
            cell.getOdfElement().setProperty(OdfTextProperties.FontWeight, "bold");
        }
        if (background != null) {
            cell.getOdfElement().setProperty(OdfTableCellProperties.BackgroundColor, background);
        }
    }

    private static void appendKV(OdfTable table, String key, double value) {
        OdfTableRow row = appendCleanRow(table);
        setText(row, 0, key, true, null);
        setMoney(row, 1, value, false, null);
    }

    private static void appendKV(OdfTable table, String key, int value) {
        OdfTableRow row = appendCleanRow(table);
        setText(row, 0, key, true, null);
        setText(row, 1, String.valueOf(value), false, null);
    }

    private static void setColumnWidths(OdfTable table) {
        String[] widths = {"0.8cm", "5.0cm", "3.5cm", "2.5cm", "2.5cm", "2.5cm", "2.8cm", "2.5cm"};
        for (int i = 0; i < table.getColumnCount() && i < widths.length; i++) {
            OdfTableColumn column = table.getColumnByIndex(i);
            if (column != null) {
                column.getOdfElement().setProperty(OdfTableColumnProperties.ColumnWidth, widths[i]);
            }
        }
    }

